/bin/zsh -lc "python3 -B - <<'PY'
import hashlib, json, os
from pathlib import Path
root=Path.cwd()
records={}
for directory, dirs, files in os.walk(root, followlinks=False):
    for name in sorted(dirs+files):
        p=Path(directory)/name
        rel=p.relative_to(root).as_posix()
        st=p.lstat()
        if p.is_symlink():
            records[rel]={'type':'symlink','target':os.readlink(p),'mode':st.st_mode}
        elif p.is_file():
            records[rel]={'type':'file','sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'mode':st.st_mode}
        elif p.is_dir():
            records[rel]={'type':'directory','mode':st.st_mode}
print(json.dumps({'workspace':str(root),'snapshot':records,'policy_sha256':hashlib.sha256(Path('/private/tmp/stdo-skills-installation-w8g_16zt/codex/control/worker-policy.json').read_bytes()).hexdigest()},sort_keys=True))
PY"

